 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            min_r = min(y for y, x in cells)
            max_r = max(y for y, x in cells)
            min_c = min(x for y, x in cells)
            max_c = max(x for y, x in cells)
            shape = {(y - min_r, x - min_c) for y, x in cells}
            objects.append((min_c, min_r, color, max_r - min_r + 1, max_c - min_c + 1, shape))
    objects.sort(key=lambda obj: (obj[0], obj[1]))
    out = [[0] * w for _ in range(h)]
    top = left = 0
    for _, _, color, oh, ow, shape in objects:
        for dy, dx in shape:
            if 0 <= top + dy < h and 0 <= left + dx < w:
                out[top + dy][left + dx] = color
        top += oh - 1
        left += ow - 1
    return out
